require "nokogiri"; doc = Nokogiri::XML(File.read("_site/sitemap.xml")); doc.xpath("//xmlns:url", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").each do |url| loc = url.xpath("xmlns:loc", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").text; lastmod = url.xpath("xmlns:lastmod", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").text; puts "Missing lastmod: #{loc}" if lastmod.empty?; puts "Internal file found: #{loc}" if loc.match?(/phase|plan|audit|report|draft|blueprint|map|roadmap/i); end; puts "Total URLs: #{doc.xpath("//xmlns:url", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").size}"
